"""Build 016 H3 benchmark based on genuine T2F-Bench sample 004."""
import os,csv,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
rows=list(csv.DictReader(open(Path(os.environ["TEMP"])/"t2f_bench_original.csv",encoding="utf-8-sig",newline="")))
source=rows[3]["ai_film_script"]
assert len(rows)==100 and all(x in source for x in ("SAL TESSIO","TOM HAGEN","WILLI CICCI","INT. CORLEONE HOUSE"))
shots=[["S01","Live-action 1970s crime drama, cloudy afternoon in an Italian-American family's private estate courtyard. Wide tracking two-shot beside a rough stone wall: Sal Tessio, an older stocky man with combed-back greying hair in a dark navy suit, walks briskly on screen left beside Tom Hagen, a middle-aged clean-shaven man with neatly parted dark brown hair in a charcoal suit and tie, on screen right. At 0–2 seconds they stride toward two parked black vintage sedans in the distance; at 2–3 seconds Tessio looks down at his wristwatch; at 3–5 seconds he quickens his steps while Tom maintains a controlled pace. The camera tracks parallel at a measured walking speed, keeping the stone wall on their left and black cars ahead. Natural gait and subtle wardrobe movement.","Gravel crunches beneath leather shoes, a light breeze brushes leaves near the stone wall, distant car engines idle.","Low sparse cello notes at a measured tempo."],["S02","Live-action 1970s crime drama, continuous stone-walled estate path under grey daylight. Wide eye-level shot facing Sal Tessio in a navy suit and Tom Hagen in charcoal as they walk toward camera. A younger broad-shouldered bodyguard named Willi Cicci, wearing a dark brown suit, emerges from the shade of a large plane tree directly ahead; two silent guards in dark coats step into the background on either side of the path. From 0–2 seconds Cicci steps forward, from 2–4 seconds the other guards appear with restrained movements, at 4–5 seconds Tessio and Tom stop. Static camera emphasizes the narrowing space; no weapons, no frantic movements.","Footsteps slow on gravel; branches rustle lightly and a car idles in the background.","Three muted low-string pulses spaced slowly."],["S03","Live-action 1970s crime drama at the estate stone wall, overcast daylight. Close medium shot of older Sal Tessio, stocky with slicked-back grey hair, in a dark navy suit, with Tom Hagen visible as an out-of-focus charcoal-suited figure at his side. From 0–1 seconds Tessio keeps a tense forward gaze; at 1–3 seconds he suddenly stops and turns toward the guards off-camera; at 3–5 seconds his face visibly falls as he realizes the trap, his jaw tightening and breath becoming shallow. The camera pushes in with small amplitude at slow speed to capture understated facial performance; realistic blinking and skin texture, no gaze toward lens.","A faint breath catches, outdoor air remains still, distant engine hum continues.","A low sustained cello tone with one soft piano accent."],["S04","Live-action cinematic 1970s crime drama beside the same estate wall. Eye-level tight alternating-profile two-shot, Sal Tessio in navy suit on frame left faces Tom Hagen in a charcoal suit on frame right; two indistinct guards stay far behind. From 0–2 seconds Tessio turns toward Tom and searches his face, visibly frightened but trying to maintain dignity; at 2–4 seconds Tom lowers his eyes for a moment before meeting Tessio's gaze, his expression pained yet firm; at 4–5 seconds Tessio's shoulders settle as understanding dawns. The camera remains completely static, keeping both faces in the same plane with shallow background focus.","Quiet fabric movement and strained breathing; faint birds and distant idling car.","Sparse muted piano notes separated by long silence."],["S05","Live-action 1970s crime drama on the wet grey stone driveway of a private estate. Medium three-quarter shot: Sal Tessio, an older stocky man in a navy suit, stands by a dark-suited younger guard Willi Cicci with Tom Hagen in charcoal two paces behind. At 0–1.5 seconds Cicci reaches forward with one hand and briefly grips Tessio's upper forearm; at 1.5–3 seconds Tessio looks down toward the hand; at 3–5 seconds he gently withdraws his arm without struggle, holding his posture straight and keeping his dignity. The camera trucks left with small amplitude at slow speed, showing realistic hand contact, coherent arms, restrained acting and fixed body positions.","Sleeves brush, shoes shift on gravel and a muted fabric tug breaks the silence.","Low held strings without percussion."],["S06","Live-action 1970s crime drama in the same overcast estate courtyard beside a rough stone wall. Intimate medium close two-shot: older Sal Tessio in navy suit stands on screen left and middle-aged Tom Hagen in charcoal suit on right. At 0–2 seconds Tessio leans slightly closer and makes a restrained, pleading motion with one open hand; at 2–3.5 seconds Tom keeps still, his eyes sad but unwavering; at 3.5–5 seconds Tessio lowers his hand and slowly nods, accepting the refusal. Gentle camera push-in with small amplitude at very slow speed. Micro-expressions and realistic natural breathing, not theatrical gestures.","A deep breath, faint rustle of wool, quiet wind beyond the wall.","A slow sequence of solitary low piano notes and soft sustained cello."],["S07","Live-action 1970s crime drama, wide medium eye-level shot of an estate driveway under a dull grey sky. Sal Tessio, older and stocky with combed-back grey hair in dark navy, stands between Willi Cicci in a brown suit and two guards in dark coats. A black 1970s sedan waits several meters ahead near the stone wall. At 0–1 seconds Tessio exhales and turns away from Tom behind him; at 1–4 seconds he walks quietly beside Cicci toward the car, the guards keeping a respectful but firm distance; at 4–5 seconds the group approaches the rear passenger door. The camera tracks behind them slowly, coherent gait and stable geography, no fighting.","Measured gravel footsteps, soft jacket creaks and subdued engine idle.","Low cello line, sparse piano repeating at a slow tempo."],["S08","Live-action 1970s crime drama on the same estate driveway in overcast daylight. Static medium-wide profile shot of the black vintage sedan parked by the stone wall. Sal Tessio in a navy suit stands by the open rear door with a younger guard in a brown suit at his side. At 0–2 seconds Tessio slowly bends and enters the back seat; at 2–3.5 seconds the guard closes the rear passenger door with one deliberate movement; at 3.5–5 seconds the black sedan begins to drive away slowly to frame right while the guard stays outside. Realistic car door hinge, no clipping through the vehicle, natural action tempo.","Car door closes with a firm low thud, engine grows slightly louder and tires roll over gravel.","Single sustained low string note, no percussion."],["S09","Live-action late-1970s interior of a dark quiet estate house during the afternoon. Tight-medium shot from inside looking toward a leaded glass window with diamond-shaped panes. Tom Hagen, a middle-aged clean-shaven man with neatly parted dark brown hair in a charcoal suit and tie, stands just behind the glass; the passing black sedan is dimly visible outdoors through the panes. From 0–2 seconds he watches the car pull away in the courtyard; at 2–3.5 seconds its dark silhouette passes across his fragmented reflection; at 3.5–5 seconds the car disappears and he remains motionless, grim and resigned. Static camera, controlled framing, no direct eye contact with lens, somber natural light.","Muffled car tires recede outside; the interior remains quiet with faint room tone and Tom's slow breath.","Low piano chord slowly decays into silence."]]
base=json.loads((root/"tasks"/"015_t2f_003_h3_skill_5s.json").read_text(encoding="utf-8"))
items=[]
for name,scene,ambience,music in shots:
    prompt=f"integrated_multimodal_description: [Shot 1] {scene}\n\noverall_soundscape: {ambience}\n\nnon_diegetic_music: {music}"
    items.append({"name":name,"set":{"140:131.prompt":prompt,"140:133.value":5,"92.filename_prefix":f"video/016_t2f_004_h3_skill_{name}"}})
task={"name":"016_t2f_004_h3_skill_5s","steps":[{"id":"video","workflow":base["steps"][0]["workflow"],"endpoint":base["steps"][0]["endpoint"],"foreach":items}]}
path=root/"tasks"/"016_t2f_004_h3_skill_5s.json"
assert not path.exists(),"Task already exists, refuse overwrite"
path.write_text(json.dumps(task,ensure_ascii=False,indent=2),encoding="utf-8")
print("PREPARED",str(path),"SHOTS",len(items))
